// Topic references identify relevant reading; original passages are the evidence
// for their own questions. IDs belong to concepts, never to mock-paper numbers.
const ref = (name, url) => ({ name: `${name} — topic reference`, url });
const SOURCES = {
  books: ref('NCERT textbook portal', 'https://ncert.nic.in/textbook.php'),
  development: ref('NCERT Psychology: Human Development', 'https://ncert.nic.in/textbook/pdf/kepy103.pdf'),
  framework: ref('NCERT National Curriculum Framework 2005', 'https://ncert.nic.in/pdf/nc-framework/nf2005-english.pdf'),
  inclusion: ref('NCERT Inclusion in Education', 'https://ncert.nic.in/pdf/announcement/Inclusion_in_Eduction.pdf'),
  english: ref('NCERT Teaching of English', 'https://ncert.nic.in/pdf/focus-group/english.pdf'),
  hindi: ref('NCERT Teaching of Indian Languages', 'https://ncert.nic.in/pdf/focus-group/Indian_Languages.pdf'),
  social: ref('NCERT Teaching of Social Sciences', 'https://ncert.nic.in/pdf/focus-group/social_sciencel.pdf'),
  credit: ref('NCERT Money and Credit', 'https://ncert.nic.in/textbook/pdf/jess203.pdf'),
};
const review = basis => ({ status: 'reviewed', date: '2026-10-30', basis });
function item(section, domain, unit, syllabusId, row, source = SOURCES.books, basis = 'New authored practice; answer and distractors reviewed') {
  const [slug, topic, question, options, answer, explanation, difficulty = 'Moderate'] = row;
  const id = `school-${slug}`;
  // Spread stored answer positions too; the sitting engine separately shuffles.
  const offset = [...id].reduce((n, c) => n + c.codePointAt(0), 0) % 4;
  return { id, section, domain, unit, topic, kind: 'content', question,
    options: options.map((_, i) => options[(i + offset) % 4]),
    correctAnswer: (answer - offset + 4) % 4, explanation, difficulty, source,
    syllabusIds: [syllabusId], review: review(basis) };
}
function legacy(bank, index, section, domain, unit, syllabusId, slug, topic, source, changes = {}) {
  const original = bank[index];
  const b = { question: original.q, options: original.opts, correctAnswer: original.ans, explanation: original.exp, ...changes };
  return item(section, domain, unit, syllabusId, [slug, topic, b.question, b.options, b.correctAnswer, b.explanation], source,
    `Adapted and reviewed from existing local ${section === 'all' ? 'NCERT' : section} bank item ${index}; no official-key claim`);
}

