function passageSet(section, slug, title, text, type, rows) {
  const domain = section === 'lang1' ? 'english' : 'hindi';
  const syllabusId = section === 'lang2' ? 'HI001' : type === 'poem' ? 'EN002' : 'EN001';
  const source = { ...SOURCES[domain], name: `Original Study Atlas passage (answer evidence); ${SOURCES[domain].name}` };
  const passage = { id: `school-passage-${slug}`, title, text, type };
  return rows.map(([key, skill, question, options, answer, explanation, difficulty])=>({
    ...item(section,domain,type==='poem'?'poetry-comprehension':'prose-comprehension',syllabusId,
      [`${section==='lang1'?'en':'hi'}-${key}`,skill,`${title}: ${question}`,options,answer,explanation,difficulty],source,
      'Original passage and questions authored for this app; answers checked against the supplied text'),
    kind:'comprehension', passage,
  }));
}
