const NCERT_FIXES = {
  2:{options:['Siraj-ud-Daulah, Mir Jafar and Dupleix','Mir Qasim, Shuja-ud-Daula and Shah Alam II','Tipu Sultan, Haidar Ali and the Peshwa','Bahadur Shah Zafar, Nana Sahib and Lakshmibai']},
  3:{question:'Which Harappan settlement is located on Khadir island in the Rann of Kutch?',explanation:'Dholavira is on Khadir island in the Rann of Kutch, Gujarat. Its location distinguishes it from the other listed sites.'},
  5:{question:'Which mangrove region lies in the Ganga–Brahmaputra delta across India and Bangladesh?',explanation:'The Sundarbans occupy part of the Ganga–Brahmaputra delta in India and Bangladesh.'},
  6:{question:'Which warm current helps moderate the climate of northwestern Europe?',options:['Labrador Current','Canary Current','North Atlantic Drift','Benguela Current'],explanation:'The North Atlantic Drift carries relatively warm water northeastward. It contributes to regional climate moderation together with atmospheric circulation; it is not the sole control of every port\'s winter conditions.'},
  8:{question:'Which practice reduces runoff speed by creating step-like fields on steep slopes?',options:['Strip cropping on level ground','Terrace cultivation','Removing vegetation from the slope','Ploughing directly up and down the slope'],correctAnswer:1,explanation:'Terraces shorten and flatten slope segments, helping slow runoff and retain soil. Unprotected cultivation down a slope can accelerate erosion.'},
  9:{question:'Which iron and steel company established in 1907 developed its works at Sakchi, later called Jamshedpur?',options:['Rourkela Steel Plant','Tata Iron and Steel Company','Bhilai Steel Plant','Durgapur Steel Plant'],explanation:'Tata Iron and Steel Company (TISCO) was established in 1907 and developed its steel works at Sakchi. Jamsetji Tata had died in 1904, so he should not be described as personally founding the 1907 plant.'},
  11:{options:['Rajya Sabha','Lok Sabha','A joint sitting before either House considers it','Either House at the sponsor\'s choice'],correctAnswer:1,explanation:'A Money Bill can be introduced only in the Lok Sabha, subject to the required presidential recommendation. The Rajya Sabha may recommend changes but does not have equal powers over it.'},
  13:{question:'Which activity best illustrates the Gram Sabha\'s role in local accountability?',options:['Reviewing local development work and questioning Panchayat expenditure','Appointing the state Chief Minister','Setting the national bank rate','Hearing an appeal against a Supreme Court judgment'],correctAnswer:0,explanation:'Village voters can question Panchayat work and expenditure through the Gram Sabha. Exact statutory functions depend on the relevant state law.'},
  15:{question:'Which institution is associated with central foodgrain buffer stocks and procurement operations, alongside state agencies?',explanation:'The Food Corporation of India participates in procurement, storage and movement of foodgrains; state agencies also conduct procurement. It is inaccurate to imply that FCI is the only procuring agency.'},
  16:{question:'Per capita income is calculated by:',options:['Dividing total income by population','Dividing population by land area','Adding the incomes of only the richest households','Multiplying every household\'s income by its size'],correctAnswer:0,explanation:'Per capita income is total income divided by population. An average does not reveal how income is distributed.'},
  17:{options:['Workers having no work at all throughout the year','More workers engaged than needed, so some can leave without reducing output','Workers moving between two jobs in the same week','All workers receiving identical wages'],explanation:'Disguised unemployment exists when some workers can be withdrawn without reducing output. It differs from open unemployment and seasonal absence of work.'},
  18:{question:'In the historical account of the consumer movement, COPRA was first enacted in which year?',explanation:'The Consumer Protection Act commonly called COPRA in school accounts was enacted in 1986. A later Consumer Protection Act was enacted in 2019, so this is a historical-year question.'},
  19:{question:'What does SHG stand for in discussions of savings and rural credit?',options:['State Housing Guild','Self Help Group','Small Holders Guarantee','Social Health Grant'],explanation:'An SHG is a Self Help Group. Members pool savings and may make loans; the group structure can also support access to bank credit.'},
};
